\label{l1} If $q\in L_{1}[0,\pi]$, then the following formula holds:
\begin{equation}
A_{1,n}(n^{2})=\frac{C_{2n}^{2}}{4n^{2}}+D(n,q)+2\operatorname{Re}D(n,p),
\label{eq14} 
\end{equation}
where $D(n,f)=D_{1}(n,f)+D_{2}(n,f)$,
\[
D_{1}(n,f)=\frac{i}{4n\pi}\int_{0}^{\pi}f(x)(Q(x,n)-Q_{n,0})e^{-i2nx} 
\,dx,\quad D_{2}(n,f)=\frac{i}{4n\pi}\int_{0}^{\pi}f(x)G(x,n)e^{-i2nx}\,dx,
\]
and $p(x)=q(-x)$.

By the definition of $A_{1,n}(n^{2})$, we have
\[
A_{1,n}(n^{2})=-\sum_{\substack{k=-\infty\\k\neq0,-2n}}^{\infty}\frac
{C_{k}^{2}}{k(2n+k)}.
\]
Since $\dfrac{1}{k(2n+k)}=\dfrac{1}{2n}\bigl(\dfrac{1}{k}-\dfrac{1} 
{2n+k}\bigr)$, we see that
\begin{equation}
A_{1,n}(n^{2})=\frac{1}{2n}\sum_{k\neq0,-2n}\frac{C_{k}^{2}}{2n+k}-\frac
{1}{2n}\sum_{k\neq0,-2n}\frac{C_{k}^{2}}{k}. \label{eq15} 
\end{equation}
Using the obvious equality $C_{-k}=C_{k}$ and $C_{0}=0,$ we obtain the
following equality for the second term on the right side of~\eqref{eq15}:
\begin{equation}
\frac{1}{2n}\sum_{k\neq0,-2n}\frac{C_{k}^{2}}{k}=\frac{C_{2n}^{2}}{4n^{2}}.
\label{eq16} 
\end{equation}


Now let us estimate the first term on the right side of~\eqref{eq15}. Since
$q_{-k}=\overline{q_{k}}$ and $\cos kx=\dfrac{1}{2}(e^{ikx}+e^{-ikx})$, we
have $C_{k}^{2}=\dfrac{1}{4}(2\left\vert q_{k}\right\vert ^{2}+q_{k} 
^{2}+q_{-k}^{2})$. Therefore, the first term on the right side of~\eqref{eq15}
can be written in the form
\begin{equation}
\frac{1}{2n}\sum_{k\neq0,-2n}\frac{C_{k}^{2}}{2n+k}=I_{1}+I_{2}+I_{3},
\label{eq17} 
\end{equation}
where
\begin{equation}
I_{1}=\frac{1}{4n}\sum_{\substack{k=-\infty\\k\neq0,-2n}}^{\infty} 
\frac{\left\vert q_{k}\right\vert ^{2}}{(2n+k)}=I_{1,1}+I_{1,2},\qquad
I_{2}=\frac{1}{8n}\sum_{\substack{k=-\infty\\k\neq0,-2n}}^{\infty}\frac
{q_{-k}^{2}}{(2n+k)},\qquad I_{3}=\overline{I_{2}}, \label{eq18} 
\end{equation} 
\[
I_{1,1}=\frac{1}{4n}\sum_{\substack{m=-\infty\\m\neq0,-n}}^{\infty} 
\frac{\left\vert q_{2m}\right\vert ^{2}}{(2n+2m)},\qquad I_{1,2}=\frac{1} 
{4n}\sum_{\substack{m=-\infty\\}}^{\infty}\frac{\left\vert q_{2m+1}\right\vert
^{2}}{(2n+2m+1)}.
\]
First, let us prove that
\begin{equation}
I_{1,1}=D_{1}(n,q),\qquad I_{1,2}=D_{2}(n,q),\qquad I_{1}=D(n,q). \label{eq19} 
\end{equation}
It is clear that $Q(\pi,n)=0$, $Q(0,n)=0$, and that the derivative of $Q(x,n)$
with respect to $x$\ is $Q^{\prime}(x,n)=q(x)e^{i2nx}\,-q_{-2n}$. Using the
integration by parts, we see that
\[
\int_{0}^{\pi}Q(x,n)e^{-i(2n+2m)x}dx=\frac{\pi q_{2m}}{i(2n+2m)},
\]
for $n+m\neq0$. Therefore, the Fourier decomposition of $Q(x,n)$ by the
orthonormal basis $\{e^{i2mx}/\sqrt{\pi}:m\in\mathbb{Z\}}$ of $L_{2}[0,\pi]$
has the form
\[
Q(x,n)=Q_{n,0}+\sum_{m\neq0,-n}\frac{q_{2m}e^{i(2n+2m)x}}{i(2n+2m)}.
\]
Using this decomposition in the integral for $D_{1}(n,q)$, we obtain the proof
of the first equality of~\eqref{eq19}.

Now, let us prove the second equality of~\eqref{eq19}. It is clear that
\[
G(\pi,n)=\int_{0}^{\pi}\bigl(q(t)e^{i2nt}\,+\frac{i\pi}{2}e^{it} 
\,q_{-2n}\bigr)dt=\pi q_{-2n}+\frac{\pi}{2}(e^{i\pi}-1)q_{-2n}=0,
\]
$G(0,n)=0$ and that $G^{\prime}(x,n)=q(x)e^{i2nx}\,+\dfrac{i\pi}{2} 
e^{ix}q_{-2n}$. Therefore,
\[
\int_{0}^{\pi}G(x,n)e^{-i(2n+2m+1)x}dx=\frac{\pi q_{2m+1}}{i(2n+2m+1)}.
\]
Thus, the Fourier decomposition of $G(x,n)$ by the orthonormal basis
$\{e^{i(2m+1)x}/\sqrt{\pi}:m\in\mathbb{Z}\}$ of $L_{2}[0,\pi]$ has the form \
\[
G(x,n)=\sum_{m\in\mathbb{Z}}\frac{q_{2m+1}e^{i(2n+2m+1)x}\,}{i(2n+2m+1)}.
\]
Using this decomposition of $G(x,n)$ in the integral for $D_{2}(n,q)$, we
obtain the proof of the second equality of~\eqref{eq19}. The third equality
of~\eqref{eq19} follows from~\eqref{eq18}.

Now, we consider $I_{2}$. Using the definition of $p(x)$ and the substitution
$t=-x$, we obtain
\[
p_{k}:=\frac{1}{\pi}\int_{0}^{\pi}p(x)e^{-ikx}dx\,=\frac{1}{\pi}\int_{0}^{\pi
}q(-x)e^{-ikx}dx\,=\frac{1}{\pi}\int_{0}^{\pi}q(t)e^{ikt}dt=q_{-k}.
\]
Therefore, instead of $q(x)$, using $p(x)$ and repeating the proof
of~\eqref{eq19}, we obtain that
\begin{equation}
I_{2}=D(n,p),\qquad I_{2}+I_{3}=2\operatorname{Re}D(n,p). \label{eq20} 
\end{equation}
Thus, the proof of~\eqref{eq14} follows from~\eqref{eq15}-\eqref{eq20}. The
lemma is proved.

\label{l2} If $q\in L_{1}[0,\pi]$, then the following formula holds
\begin{equation}
B_{1,n}(n^{2})=-\frac{1}{\pi}\int_{0}^{\pi}Q^{2}(x)\cos2nxdx, \label{eq21} 
\end{equation}
where $Q(x)=$ $ 
                          
               
{\displaystyle\int_{0}^{x}}
             
q(x)dx$.

\label{l3} If $q\in E$, then the equalities
\begin{equation}
S_{j}(n,q)=O\bigl(\frac{1}{n}\bigr), \label{eq27} 
\end{equation}
for $j=2,3,4$, hold.

\label{t1}If $q\in E$, then the following asymptotic formula holds:
\begin{equation}
\lambda_{n}=n^{2}-C_{2n}+\frac{1}{\pi}\int_{0}^{\pi}Q^{2}(x)\cos
2nxdx+D(n,q)+2\operatorname{Re}D(n,p)+O\bigl(\frac{1}{n^{3}}\bigr),
\label{eq30} 
\end{equation}
where $D(n,f)$ and $Q(x)$ are defined in Lemma~\ref{l1} and Lemma~\ref{l2}.

It follows from~\eqref{eq8},~\eqref{eq25} and~\eqref{eq26} that $\lambda
_{n}=n^{2}+O\bigl(\dfrac{1}{n}\bigr)$. Using this, we easily get the estimate
\[
\sum_{\substack{k\neq0,-2n}}^{\infty}\biggl|\frac{1}{\lambda_{n}-(n+k)^{2} 
}-\frac{1}{n^{2}-(n+k)^{2}}\biggr|=O\bigl(\frac{1}{n^{3}}\bigr).
\]
By virtue of this estimate
\[
a_{j}\left(  \lambda_{n}\right)  =a_{j}\left(  n^{2}\right)  +O\bigl(\frac
{1}{n^{3}}\bigr),
\]
for $j=1,2,\ldots$. Therefore, it follows from~\eqref{eq2}-\eqref{eq6} that
\begin{equation}
\lambda_{n}=n^{2}-C_{2n}+a_{1}\left(  n^{2}\right)  +a_{2}\left(
n^{2}\right)  +a_{3}\left(  n^{2}\right)  +O\bigl(\frac{1}{n^{3}}\bigr),
\label{eq31} 
\end{equation}
where $a_{1}(n^{2})=A_{1,n}(n^{2})-B_{1,n}(n^{2})$, equivalently
\begin{equation}
a_{1}\left(  n^{2}\right)  =\frac{1}{\pi}\int_{0}^{\pi}Q^{2}(x)\cos
2nxdx+D(n,q)+2\operatorname{Re}D(n,p)+O\bigl(\frac{1}{n^{3}} 
\bigr) \label{eq32} 
\end{equation}
(see Lemma~\ref{l1}, Lemma~\ref{l2} and~\eqref{eq25}), and
\begin{equation}
a_{2}\left(  n^{2}\right)  =O\bigl(\frac{1}{n^{3}}\bigr) \label{eq33} 
\end{equation}
(see~\eqref{eq28} and~\eqref{eq29}). On the other hand, we have
\[
a_{3}\left(  n^{2}\right)  =\sum_{n_{1},n_{2},...,n_{k}=-\infty}^{\infty} 
\frac{C_{k}C_{l}C_{s}(C_{k+l+s}-C_{2n+k+l+s})} 
{k(2n+k)(k+l)(2n+k+l)(k+l+s)(2n+k+l+s)}.
\]
Moreover, arguing as in the proof of~\eqref{eq33}, we see that $a_{3}\left(
n^{2}\right)  =O\bigl(\dfrac{1}{n^{3}}\bigr)$. Thus, the proof of the theorem
follows from~\eqref{eq31}-\eqref{eq33}.

\label{t2} If $q(x)$ has the form~\eqref{eq9}, then the following asymptotic
formula holds:
\[
\lambda_{n}=n^{2}+\frac{b-a}{2\pi n}\sin2nc+\frac{ab(1-2\cos2nc)}{4n^{2} 
}+O\bigl(\frac{1}{n^{3}}\bigr).
\]

\label{l4} If the assumptions about $M$ given in Condition~\ref{c1}
hold,\ then the statements

\textbf{(a)} $\lim_{m\rightarrow\infty}R_{m}(\lambda)=0,$ and \textbf{(b)}
$|(\Psi_{n},\sin nx)|>0$

are valid, where\ $R_{m}(\lambda)$ is defined by~\eqref{eq6}.

\begin{proof}
\textbf{ (a)} Since $||\Psi_{n}||=1$ and $||\sin kx||=\sqrt{\pi}/\sqrt{2}$, by
the Schwarz inequality, we have $|(q\Psi_{n},\sin kx)|\leq M\sqrt{\pi} 
/\sqrt{2}$. Considering the number of terms and the greatest summands of
$R_{2m}(\lambda)$ in absolute value, by~\eqref{eq43}, we obtain,
\[
|R_{2m}(\lambda_{1})|<\frac{4^{m}|C_{1}||C_{2}|^{2m}M\sqrt{\pi}/\sqrt{2} 
}{(2n-1-M)^{2m+1}}<\frac{(b-a)}{\sqrt{2\pi}}(\frac{2}{\pi})^{2m}.
\]
Therefore, $\lim_{m\rightarrow\infty}R_{m}(\lambda)=0$.

\textbf{(b)} Suppose the contrary, $(\Psi_{n},\sin nx)=0$. Since the system of
root functions $\{\sqrt{2}\sin kx/\sqrt{\pi}:k\in\mathbb{N}\}$ of $L(0)$ forms
an orthonormal basis for $L_{2}[0,\pi]$, we have the decomposition
\[
\dfrac{\pi}{2}\Psi_{n}=(\Psi_{n},\sin nx)\sin nx+\sum_{k\in\mathbb{N},k\neq
n}\left(  \Psi_{n},\sin kx\right)  \sin kx
\]
for the normalized eigenfunction $\Psi_{n}$ corresponding to the eigenvalue
$\lambda_{n}$ of $L(q)$. By Parseval's equality, we obtain
\begin{equation}
\sum_{k\in\mathbb{N},k\neq n}|\left(  \Psi_{n},\sin kx\right)  |^{2}=\frac
{\pi}{2} \label{eq44} 
\end{equation}
On the other hand, using the relation $(\lambda_{N}-n^{2})(\Psi_{N},\sin
nx)=(q\Psi_{N},\sin nx)$, the Bessel inequality and~\eqref{eq43}, we obtain
\begin{align*}
&  \sum_{k\in\mathbb{N},k\neq n}|\left(  \Psi_{n},\sin kx\right)  |^{2} 
=\sum_{k\in\mathbb{N},k\neq n}\frac{|(q\Psi_{n},\sin kx)|^{2}}{|\lambda
_{n}-k^{2}|^{2}}\\
&  \qquad\leq\frac{1}{(2n-1-M)^{2}}\sum_{k\in\mathbb{Z},k\neq\pm n}|(q\Psi
_{n},\sin kx)|^{2}<\frac{\pi(M)^{2}}{2(2n-1-M)^{2}}<\frac{\pi}{2}.
\end{align*}
which contradicts Parseval's equality~\eqref{eq44}.
\end{proof}

\label{t4} Suppose that the assumptions about $M$ given in Condition~\ref{c1}
hold. Then for all $x$ and $y$ from the interval $I_{n}=[n^{2}-M,n^{2}+M]$,
the relations
\begin{gather}
|g_{n}(x)-g_{n}(y)|\leq L_{n}|x-y|,\label{eq48}\\
L_{n}=\frac{9(b-a)^{2}}{4\pi(2n-1-M)[4\pi(2n-1-M)-3(b-a)]}\leq\frac{9} 
{2\pi(2\pi-3)}<1,\nonumber
\end{gather}
hold and equation~\eqref{eq47} has a unique solution $\rho_{n}$ in $I_{n}$.
Moreover
\begin{align}
&  |\lambda_{n}-\rho_{n}|<\frac{(b-a)^{s+2}}{2M\sqrt{2}^{s}\pi^{s+1} 
(2n-1-M)^{s}[\sqrt{2}\pi(2n-1-M)-(b-a)](1-L_{n})}\nonumber\\
&  \qquad+\frac{8(b-a)^{2}}{\pi^{2}(r+1)^{2}[(r+1)|r+1-2n|-M](1-L_{n})}.
\label{eq49} 
\end{align}

First, we prove~\eqref{eq48} by using the mean-value theorem. To do this, we
estimate $|g_{n}^{\prime}(\lambda)|=|\dfrac{d}{d\lambda}g_{n}(\lambda)|$.
By~\eqref{eq46}, we have
\[
|g_{n}^{\prime}(\lambda)|=\biggl|\sum\limits_{k=1}^{s}\frac{d}{d\lambda
}a_{r,k,n}(\lambda)\biggr|\leq\sum\limits_{k=1}^{s}\bigl|\frac{d}{d\lambda
}a_{r,k,n}(\lambda)\bigr|.
\]
By estimating the summands of the term $|\dfrac{d}{d\lambda}a_{r,k,n} 
(\lambda)|$, we write
\begin{align*}
&  \biggl|\frac{d}{d\lambda}(a_{r,k,n}(\lambda))\biggr|=\biggl|\sum
_{n_{1},n_{2},...,n_{k}=-r}^{r}\frac{d}{d\lambda}\frac{C_{n_{1}}C_{n_{2} 
}\cdots C_{n_{k}}(C_{n_{1}+n_{2}+\cdots+n_{k}}-C_{n_{1}+n_{2}+\cdots+n_{k} 
+2n})}{[\lambda-(n+n_{1})^{2}]\cdots\lbrack\lambda-(n+n_{1}+\cdots+n_{k} 
)^{2}]}\biggr|\\
&  \qquad<\frac{3^{k+1}(b-a)^{k+1}}{4^{k+1}\pi^{k+1}(2n-1-M)^{k+1}} 
\leq\bigl|\frac{3}{2\pi}\bigr|^{k+1},
\end{align*}
for $k\geq1$. Thus, by the geometric series formula, we obtain
\[
\sum\limits_{k=1}^{r}\bigl|\frac{d}{d\lambda}a_{r,k,n}(\lambda)\bigr|<\frac
{9}{2\pi(2\pi-3)}.
\]
Hence,
\begin{equation}
|g_{n}^{\prime}(\lambda)|<\frac{9(b-a)^{2}}{4\pi(2n-1-M)[4\pi(2n-1-M)-3(b-a)]} 
=L_{n}\leq\frac{9}{2\pi(2\pi-3)}<1.\label{eq50} 
\end{equation}
Since the inequality
\begin{equation}
|g_{n}^{\prime}(\lambda)|<L_{n}<1\label{eq51} 
\end{equation}
holds for all $x,y\in I_{n}$,~\eqref{eq48} holds by the mean value theorem and
equation~\eqref{eq47} has a unique solution $\rho_{n}$ in $I_{n}$, by the
contraction mapping theorem. Now let us prove~\eqref{eq49}. By~\eqref{eq46},
we have $K_{n}(x)=x-n^{2}-g_{n}(x)$ and by the definition of $\rho_{n}$, we
write $K_{n}(\rho_{n})=0$. Therefore by~\eqref{eq42} and~\eqref{eq47}, we
obtain
\begin{align}
&  |K_{n}(\lambda_{n})-K_{n}(\rho_{n})|=|K_{n}(\lambda_{n})|\nonumber\\
&  \qquad=\biggl|\lambda_{n}-n^{2}+C_{2n}-\sum\limits_{k=1}^{s}a_{r,k,n} 
(\lambda_{n})\biggr|\nonumber\\
&  \qquad\leq\biggl|\sum\limits_{k=1}^{\infty}a_{k}(\lambda_{n})-\sum
\limits_{k=1}^{s}a_{r,k,n}(\lambda_{n})\biggr|.\label{eq52} 
\end{align}
For the estimation of the right-hand side of~\eqref{eq52}, we have
\begin{align*}
&  \biggl|\sum\limits_{k=1}^{\infty}a_{k}(\lambda_{n})-\sum\limits_{k=1} 
^{s}a_{r,k,n}(\lambda_{n})\biggr|\\
&  \qquad\leq\biggl|\sum\limits_{k=1}^{\infty}a_{k}(\lambda_{n})-\sum
\limits_{k=1}^{s}a_{k}(\lambda_{n})\biggr|+\biggl|\sum\limits_{k=1}^{s} 
a_{k}(\lambda_{n})-\sum\limits_{k=1}^{s}a_{r,k,n}(\lambda_{n})\biggr|\\
&  \qquad\leq\sum\limits_{k=s+1}^{\infty}|a_{k}(\lambda_{n})|+\sum
\limits_{k=1}^{s}|a_{k}(\lambda_{n})-a_{r,k,n}(\lambda_{n})|.
\end{align*}
Using the estimations for $\sum\limits_{k=s+1}^{\infty}|a_{k}(\lambda_{n} 
)|$\ and $\sum\limits_{k=1}^{s}|a_{k}(\lambda_{n})-a_{r,k,n}(\lambda_{n})|$,
by considering the greatest summands of them, we obtain
\begin{align}
&  \biggl|\sum\limits_{k=1}^{\infty}a_{k}(\lambda_{n})-\sum\limits_{k=1} 
^{s}a_{r,k,n}(\lambda_{n})\biggr|<\sum\limits_{k=s+1}^{\infty}\frac
{(b-a)^{k+1}}{2M\sqrt{2}^{k}\pi^{k+1}(2n-1-M)^{k}}+\frac{8(b-a)^{2}}{\pi
^{2}(r+1)^{2}[(r+1)|r+1-2n|-M]}\nonumber\\
&  \qquad=\frac{(b-a)^{s+2}}{2M\sqrt{2}^{s}\pi^{s+1}(2n-1-M)^{s}[\sqrt{2} 
\pi(2n-1-M)-(b-a)]}+\frac{8(b-a)^{2}}{\pi^{2}(r+1)^{2}[(r+1)|r+1-2n|-M]} 
.\label{eq53} 
\end{align}
Thus, by~\eqref{eq52} and~\eqref{eq53}, we have
\begin{align}
&  |K_{n}(\lambda_{n})-K_{n}(\rho_{n})|<\frac{(b-a)^{s+2}}{2M\sqrt{2}^{s} 
\pi^{s+1}(2n-1-M)^{s}[\sqrt{2}\pi(2n-1-M)-(b-a)]}\nonumber\\
&  \qquad+\frac{8(b-a)^{2}}{\pi^{2}(r+1)^{2}[(r+1)|r+1-2n|-M]}.\label{eq54} 
\end{align}
To apply the mean value theorem, we estimate $|K_{n}^{\prime}(\lambda)|$:
\begin{equation}
|K_{n}^{\prime}(\lambda)|=|1-g_{n}^{\prime}(\lambda)|\geq|1-|g_{n}^{\prime
}(\lambda)||\geq1-L_{n}.\label{eq55} 
\end{equation}
By the mean value formula,~\eqref{eq50},~\eqref{eq51},~\eqref{eq54}
and~\eqref{eq55}, we obtain
\[
|K_{n}(\lambda_{n})-K_{n}(\rho_{n})|=|K_{n}^{\prime}(\xi)||\lambda_{n} 
-\rho_{n}|,\qquad\xi\in\lbrack n^{2}-M,n^{2}+M]
\]
and
\begin{align*}
&  |\lambda_{n}-\rho_{n}|=\frac{|K_{n}(\lambda_{n})-K_{n}(\rho_{n})|} 
{|K_{n}^{\prime}(\xi)|}<\frac{(b-a)^{s+2}}{2M\sqrt{2}^{s}\pi^{s+1} 
(2n-1-M)^{s}[\sqrt{2}\pi(2n-1-M)-(b-a)](1-L_{n})}\\
&  \qquad+\frac{8(b-a)^{2}}{\pi^{2}(r+1)^{2}[(r+1)|r+1-2n|-M](1-L_{n})},
\end{align*}
which completes the proof.

\label{t5} If the assumptions about $M$ given in Condition~\ref{c1} hold, then
the following estimation holds for the sequence $\{x_{n,i}\}$ defined
by~\eqref{eq56}:
\begin{align}
&  |x_{n,i}-\rho_{n}|<(L_{n})^{i}\biggl(\frac{(b-a)}{2\pi n(1-L_{n})} 
+\frac{(b-a)^{2}}{M\pi^{2}(2n-1)(1-L_{n})}\nonumber\\
&  \qquad+\frac{(b-a)^{3}}{2\sqrt{2}M\pi^{2}(2n-1)[\sqrt{2}\pi
(2n-1)-(b-a)](1-L_{n})}\biggr), \label{eq60} 
\end{align}
for $i=1,2,3,\ldots$, where $L_{n}$ is defined in~\eqref{eq48} in
Theorem~\ref{t4}.

Without loss of generality, we can take $x_{n,0}=n^{2}$.
By~\eqref{eq47},~\eqref{eq48}, and~\eqref{eq56}, we have
\begin{align}
&  |x_{n,i}-\rho_{n}|=|n^{2}+g_{n}(x_{n,i-1})-(n^{2}+g_{n}(\rho_{n} 
))|\nonumber\\
&  \qquad=|g_{n}(x_{n,i-1})-g_{n}(\rho_{n})|<L_{n}|x_{n,i-1}-\rho_{n} 
|<(L_{n})^{i}|x_{n,0}-\rho_{n}|. \label{eq61} 
\end{align}
Therefore, it is enough to estimate $|x_{n,0}-\rho_{n}|$. By definitions of
$\rho_{n}$ and $x_{n,0}$, we obtain
\[
\rho_{n}-x_{n,0}=g_{n}(\rho_{n})+n^{2}-x_{n,0}=g_{n}(\rho_{n})-g_{n} 
(x_{n,0})+g_{n}(n^{2})
\]
and by the mean value theorem, there exists $x\in\lbrack n^{2}-M,n^{2}+M]$
such that
\[
g_{n}(\rho_{n})-g_{n}(x_{n,0})=g_{n}^{\prime}(x)(\rho_{n}-x_{n,0}).
\]
The last two equalities imply that
\[
(\rho_{n}-x_{n,0})(1-g_{n}^{\prime}(x))=g_{n}(n^{2}).
\]
Hence by~\eqref{eq51},~\eqref{eq59}, and~\eqref{eq61}, we have
\begin{align*}
&  |\rho_{n}-x_{n,0}|\leq\frac{|g_{n}(n^{2}))|}{1-L_{n}}<\frac{(b-a)}{2\pi
n(1-L_{n})}+\frac{(b-a)^{2}}{M\pi^{2}(2n-1)(1-L_{n})}\\
&  \qquad+\frac{(b-a)^{3}}{2\sqrt{2}M\pi^{2}(2n-1)[\sqrt{2}\pi
(2n-1)-(b-a)](1-L_{n})} 
\end{align*}
and
\begin{align*}
&  |x_{n,i}-\rho_{n}|<(L_{n})^{i}\biggl(\frac{(b-a)}{2\pi n(1-L_{n})} 
+\frac{(b-a)^{2}}{M\pi^{2}(2n-1)(1-L_{n})}\\
&  \qquad+\frac{(b-a)^{3}}{2\sqrt{2}M\pi^{2}(2n-1)[\sqrt{2}\pi
(2n-1)-(b-a)](1-L_{n})}\biggr).
\end{align*}
The theorem is proved.
